macro_rules! impl_270 {
    () => {
        deps!();
        impl < 'db > Expectation < 'db > { # [doc = " The expectation that the type of the expression needs to equal the given"] # [doc = " type."] fn has_type (ty : Ty < 'db >) -> Self { if ty . is_ty_error () { Expectation :: None } else { Expectation :: HasType (ty) } } # [doc = " The following explanation is copied straight from rustc:"] # [doc = " Provides an expectation for an rvalue expression given an *optional*"] # [doc = " hint, which is not required for type safety (the resulting type might"] # [doc = " be checked higher up, as is the case with `&expr` and `box expr`), but"] # [doc = " is useful in determining the concrete type."] # [doc = ""] # [doc = " The primary use case is where the expected type is a fat pointer,"] # [doc = " like `&[isize]`. For example, consider the following statement:"] # [doc = ""] # [doc = "     let it: &[isize] = &[1, 2, 3];"] # [doc = ""] # [doc = " In this case, the expected type for the `&[1, 2, 3]` expression is"] # [doc = " `&[isize]`. If however we were to say that `[1, 2, 3]` has the"] # [doc = " expectation `ExpectHasType([isize])`, that would be too strong --"] # [doc = " `[1, 2, 3]` does not have the type `[isize]` but rather `[isize; 3]`."] # [doc = " It is only the `&[1, 2, 3]` expression as a whole that can be coerced"] # [doc = " to the type `&[isize]`. Therefore, we propagate this more limited hint,"] # [doc = " which still is useful, because it informs integer literals and the like."] # [doc = " See the test case `test/ui/coerce-expect-unsized.rs` and #20169"] # [doc = " for examples of where this comes up,."] fn rvalue_hint (ctx : & mut InferenceContext < '_ , 'db > , ty : Ty < 'db >) -> Self { match ctx . struct_tail_without_normalization (ty) . kind () { TyKind :: Slice (_) | TyKind :: Str | TyKind :: Dynamic (..) => { Expectation :: RValueLikeUnsized (ty) } _ => Expectation :: has_type (ty) , } } # [doc = " This expresses no expectation on the type."] fn none () -> Self { Expectation :: None } fn resolve (& self , table : & mut unify :: InferenceTable < 'db >) -> Expectation < 'db > { match self { Expectation :: None => Expectation :: None , Expectation :: HasType (t) => Expectation :: HasType (table . shallow_resolve (* t)) , Expectation :: Castable (t) => Expectation :: Castable (table . shallow_resolve (* t)) , Expectation :: RValueLikeUnsized (t) => { Expectation :: RValueLikeUnsized (table . shallow_resolve (* t)) } } } fn to_option (& self , table : & mut unify :: InferenceTable < 'db >) -> Option < Ty < 'db > > { match self . resolve (table) { Expectation :: None => None , Expectation :: HasType (t) | Expectation :: Castable (t) | Expectation :: RValueLikeUnsized (t) => Some (t) , } } fn only_has_type (& self , table : & mut unify :: InferenceTable < 'db >) -> Option < Ty < 'db > > { match self { Expectation :: HasType (t) => Some (table . shallow_resolve (* t)) , Expectation :: Castable (_) | Expectation :: RValueLikeUnsized (_) | Expectation :: None => { None } } } fn coercion_target_type (& self , table : & mut unify :: InferenceTable < 'db >) -> Ty < 'db > { self . only_has_type (table) . unwrap_or_else (| | table . next_ty_var ()) } # [doc = " Comment copied from rustc:"] # [doc = " Disregard \"castable to\" expectations because they"] # [doc = " can lead us astray. Consider for example `if cond"] # [doc = " {22} else {c} as u8` -- if we propagate the"] # [doc = " \"castable to u8\" constraint to 22, it will pick the"] # [doc = " type 22u8, which is overly constrained (c might not"] # [doc = " be a u8). In effect, the problem is that the"] # [doc = " \"castable to\" expectation is not the tightest thing"] # [doc = " we can say, so we want to drop it in this case."] # [doc = " The tightest thing we can say is \"must unify with"] # [doc = " else branch\". Note that in the case of a \"has type\""] # [doc = " constraint, this limitation does not hold."] # [doc = ""] # [doc = " If the expected type is just a type variable, then don't use"] # [doc = " an expected type. Otherwise, we might write parts of the type"] # [doc = " when checking the 'then' block which are incompatible with the"] # [doc = " 'else' branch."] fn adjust_for_branches (& self , table : & mut unify :: InferenceTable < 'db >) -> Expectation < 'db > { match * self { Expectation :: HasType (ety) => { let ety = table . structurally_resolve_type (ety) ; if ety . is_ty_var () { Expectation :: None } else { Expectation :: HasType (ety) } } Expectation :: RValueLikeUnsized (ety) => Expectation :: RValueLikeUnsized (ety) , _ => Expectation :: None , } } }
    };
}

